mapper.select:
SELECT id, module, actor_id AS actorId, actor_name AS actorName, actor_role AS actorRole, client_ip AS clientIp, action, target_type AS targetType, target_id AS targetId, reason, outcome, duration_ms AS durationMs, created_at AS createdAt FROM admin_audit_log WHERE created_at >= #{from} AND created_at < #{to}
AND module = #{module}
AND action = #{action}
AND actor_id = #{actorId}
AND CONCAT_WS(' ', action, actor_name, target_type, target_id, reason) LIKE CONCAT('%', #{keyword}, '%') ESCAPE '\\'
ORDER BY created_at DESC, id DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM admin_audit_log
WHERE created_at >= #{from}
  AND created_at < #{to}

    AND module = #{module}


    AND action = #{action}


    AND actor_id = #{actorId}


    AND CONCAT_WS(' ', action, actor_name, target_type, target_id, reason)
        LIKE CONCAT('%', #{keyword}, '%') ESCAPE '\\'
